/**
 * Timeline summary block — a derived overview of the clip layers in a
 * document, written into the file for scannability.
 *
 * **Derived, not canonical.** The layers themselves are the source of truth;
 * the timeline block is regenerated by the compose pipeline (or any writer)
 * on save. Readers may use it as a fast-scan hint ("what clips, on what
 * tracks, at what times?") but tolerate it being missing or stale — when in
 * doubt, walk `doc.layers`.
 *
 * Introduced in v1.0 to solve the discoverability gap of "where are the
 * clips in this 200-line .atelier file?" — see L-2026-05-27 on the
 * multi-track + timeline-block design.
 */

/** Per-clip placement entry inside a track summary */
export interface TimelineClip {
  /** Layer id of the clip layer in `doc.layers` */
  layerId: string;
  /** Composition frame the clip starts at (inclusive) */
  startFrame: number;
  /** Composition frame the clip ends at (exclusive) */
  endFrame: number;
  /** Original source path (e.g. media/IMG_7346.MOV) — convenience copy of the asset src */
  source: string;
}

/** A track in the timeline summary — one row of sequential clips */
export interface TimelineTrack {
  /** Layer id of the Group layer that holds this track's clips */
  id: string;
  /** Track kind — what flavor of clip lives here */
  kind: "video" | "audio";
  /** Clips on this track, ordered by startFrame ascending */
  clips: TimelineClip[];
}

/**
 * Top-level timeline summary. Optional on the document: when present, gives
 * tools and humans a one-block overview of every clip's placement.
 */
export interface Timeline {
  /** Frames per second (copy of canvas.fps for convenience) */
  fps: number;
  /** Total composition length in frames — typically max(clip.endFrame) across tracks */
  totalFrames: number;
  /** Tracks, ordered as they should appear in editor UIs (top to bottom) */
  tracks: TimelineTrack[];
}
